#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 65535

int main() {
    int flaw;
    scanf("%d", &flaw);

    char s[MAX_SIZE];
    scanf("%s", s);

    char* yuan = "aeiouAEIOU";

    int idxs[MAX_SIZE];
    int idxs_size = 0;

    int i = 0;
    while (s[i] != '\0') {
        if(strchr(yuan, s[i]) != NULL) {
            idxs[idxs_size++] = i;
        }
        i++;
    }

    int ans = 0;
    int n = idxs_size;

    int l = 0;
    int r = 0;

    while(r < n) {
        // 瑕疵度计算
        int diff = idxs[r] - idxs[l] - (r - l);

        if(diff > flaw) {
            l++;
        } else if(diff < flaw) {
            r++;
        } else {
            ans = MAX(ans, idxs[r] - idxs[l] + 1);
            r++;
        }
    }

    printf("%d\n", ans);

    return 0;
}
